{
"opening": "To unify the caching decorators and enhance exception handling flexibility, we need to align the public API surfaces of @memoize and @cache while extending @reraise. These changes ensure consistent behavior across decorators and allow for dynamic exception transformation.",
"requirements": [
{
"id": "m01",
"text": "A function decorated with @memoize must expose an .invalidate(*args, **kwargs) method to remove a single cached entry and an .invalidate_all() method to clear all cached results."
},
{
"id": "m02",
"text": "A function decorated with @cache(timeout) must expose a .memory attribute containing the internal cache dictionary and a .skip attribute referencing the SkipMemoization exception class."
},
{
"id": "m03",
"text": "The into parameter of @reraise must accept a callable that receives the caught exception and returns the new exception to raise, in addition to supporting exception classes or instances."
}
]
}
